SELECT PetType, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT Student.Fname, Student.LName, Student.Age
FROM Student
JOIN Has_Pet ON Student.StuID = Has_Pet.StuID;

SELECT DISTINCT s.Fname, s.LName, s.Age
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT Year, AVG(Weight) AS AverageWeight
FROM cars_data
GROUP BY Year;

SELECT Cylinders, MAX(Accelerate) AS MaxAcceleration
FROM cars_data
GROUP BY Cylinders;

SELECT Cylinders, MAX(Accelerate) AS MaxAcceleration
FROM cars_data
GROUP BY Cylinders;

SELECT Template_Type_Code, COUNT(*) AS Template_Count
FROM Templates
GROUP BY Template_Type_Code;

SELECT country_code, COUNT(*) AS player_count
FROM players
GROUP BY country_code;

SELECT ranking_date, SUM(tours) AS total_tours
FROM rankings
GROUP BY ranking_date;

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;

SELECT DISTINCT a.*
FROM Addresses a
JOIN Students s ON s.current_address_id = a.address_id;

SELECT grade, COUNT(*) AS student_count
FROM Highschooler
